    10	  // The IAM member string (`serviceAccount:{email}`) is provided by the base class as `.member`.
    11	
    12	  /**
    13	   * Lets the given members run operations as, and mint tokens for (impersonate), this service
    14	   * account.
    15	   */
    16	  allowImpersonation(members: string[]): void {
    17	    for (const member of members) {
    18	      new gcp.serviceaccount.IAMMember(`${member}-user`, {
    19	        serviceAccountId: this.name,
    20	        role: "roles/iam.serviceAccountUser",
    21	        member,
    22	      });
    23	
    24	      new gcp.serviceaccount.IAMMember(`${member}-impersonator`, {
    25	        serviceAccountId: this.name,
    26	        role: "roles/iam.serviceAccountTokenCreator",
    27	        member,
    28	      });
    29	    }
    30	  }
    31	}

