=== compute.ts ===
     1	import * as pulumi from "@pulumi/pulumi";
     2	import * as gcp from "@pulumi/gcp";
     3	import { deployers, location, projectId } from "./config";
     4	import { network, subnet, substrateTag } from "./network";
     5	import { substrateUserData } from "./substrate-bootstrap";
     6	import { enableService } from "./services";
     7	import { ServiceAccount } from "./service-account";
     8	
     9	// Machine type for the substrate VM (Tier B floor). Resize to e2-standard-2 when load requires it —
    10	// a reboot, not a rebuild.
    11	const machineType = new pulumi.Config().get("substrateMachineType") ?? "e2-medium";
    12	
    13	const computeApi = enableService("compute.googleapis.com");
    14	const osLoginApi = enableService("oslogin.googleapis.com");
    15	const iapApi = enableService("iap.googleapis.com");
    16	
    17	/** The substrate VM's zone - exported so substrate-apply.ts's SSH commands target the same zone
    18	 * the instance actually lives in, rather than re-deriving it and risking drift. */
    19	export const zone = `${location}-b`;
    20	
    21	// Identity the substrate VM (and the containers it runs) act as. App-specific grants — Cloud SQL
    22	// client, Secret Manager access — are added in the slices that deploy the apps that need them; this
    23	// covers only what the host itself needs.
    24	export const substrateRunner = new ServiceAccount(
    25	  "substrate-runner",
    26	  "Service account for the substrate VM and its containers.",
    27	);
    28	
    29	// Host-level observability: let the VM ship logs and metrics to Cloud Monitoring/Logging.
    30	for (const role of ["roles/logging.logWriter", "roles/monitoring.metricWriter"]) {
    31	  new gcp.projects.IAMMember(`substrate-runner-${role.replace("roles/", "")}`, {
    32	    project: projectId,
    33	    role,
    34	    member: substrateRunner.member,
    35	  });
    36	}
    37	
    38	// Let deployers reach the VM over IAP-brokered SSH (no public SSH port).
    39	for (const deployer of deployers) {
    40	  for (const role of ["roles/iap.tunnelResourceAccessor", "roles/compute.osLogin"]) {
    41	    new gcp.projects.IAMMember(
    42	      `substrate-ssh-${role.replace("roles/", "")}-${deployer}`,
    43	      {
    44	        project: projectId,
    45	        role,
    46	        member: deployer,
    47	      },
    48	      { dependsOn: iapApi },
    49	    );
    50	  }
    51	}
    52	
    53	// Stable external address for the VM, so DNS can point at it and survive VM replacement.
    54	export const address = new gcp.compute.Address("substrate", {
    55	  region: location,
    56	  addressType: "EXTERNAL",
    57	});
    58	
    59	// The substrate host: Container-Optimized OS, running the app containers behind Caddy + oauth2-proxy.
    60	// The compose stack (Caddy, oauth2-proxy, and the apps themselves) is deployed in the app slices;
    61	// this stands up a ready container host. DNS A records are added when a surface actually serves.
    62	export const instance = new gcp.compute.Instance(
    63	  "substrate",
    64	  {
    65	    machineType,
    66	    zone,
    67	    tags: [substrateTag],
    68	    bootDisk: {
    69	      initializeParams: {
    70	        image: "cos-cloud/cos-stable",
    71	        size: 30,
    72	        type: "pd-balanced",
    73	      },
    74	    },
    75	    networkInterfaces: [
    76	      {
    77	        subnetwork: subnet.id,
    78	        accessConfigs: [{ natIp: address.address }],
    79	      },
    80	    ],
    81	    serviceAccount: {
    82	      email: substrateRunner.email,
    83	      scopes: ["cloud-platform"],
    84	    },
    85	    // OS Login ties SSH access to IAM (the grants above) instead of managing keys by hand.
    86	    // `user-data` is COS cloud-init: it boots the compose stack on first boot (see
    87	    // substrate-bootstrap.ts). Replacing the VM re-runs it; changing it on a running VM does not.
    88	    metadata: { "enable-oslogin": "TRUE", "user-data": substrateUserData },
    89	    // Allow machine-type resize (e2-medium -> e2-standard-2) without recreating the VM.
    90	    allowStoppingForUpdate: true,
    91	  },
    92	  {
    93	    dependsOn: [network, computeApi, osLoginApi],
    94	    // The instance's only external IP is the fixed `address` above, reused across replacements so
    95	    // DNS survives them — but that means a normal create-before-delete replace fails outright
    96	    // (a static external IP can't be attached to two instances at once). Delete the old instance
    97	    // first instead; the brief downtime is expected for a stateless container host anyway.
    98	    deleteBeforeReplace: true,
    99	  },
   100	);
   101	
   102	export const publicIp = address.address;

