     9	  "artifact-repository",
    10	  {
    11	    location,
    12	    repositoryId: "artifact-docker-repository",
    13	    format: "DOCKER",
    14	    dockerConfig: {
    15	      immutableTags: false,
    16	    },
    17	  },
    18	  { dependsOn: artifactRegistryApi },
    19	);
    20	
    21	export const artifactRepositoryUrl = pulumi.concat(
    22	  location,
    23	  "-docker.pkg.dev/",
    24	  projectId,
    25	  "/",
    26	  artifactRepository.repositoryId,
    27	);
    28	
    29	export const artifactRepositoryAccess = deployers.map((deployer) => {
    30	  return new gcp.artifactregistry.RepositoryIamMember(`artifact-member-${deployer}`, {
    31	    project: artifactRepository.project,
    32	    location: artifactRepository.location,
    33	    repository: artifactRepository.name,
    34	    role: "roles/artifactregistry.writer",
    35	    member: deployer,
    36	  });
    37	});

